    else:
        C=sp.Matrix(p['matrix']);n=C.rows;k=C.cols;answer=n-k
        indices=p['indices'];vector=matrix_tex([[expr(row,indices)] for row in p['matrix']]);variables=','.join(f'{{x}}_{{{i}}}' for i in indices)
        space=r'\text{Null}(A)=\{'+vector+r'\,|\,\,'+variables+r'\in R\}'
        problem=('Find $'+r'\text{rank}(A)'+'$ given that\n\n$$\n'+space+'.\n$$') if template=='null-space-display' else 'Find $'+r'\text{rank}(A)'+'$ given that $'+space+'.$'
        expanded='+'.join(f'{{x}}_{{{indices[j]}}}'+matrix_tex([[C[i,j]] for i in range(n)]) for j in range(k))
        solution=intro+f'For the given matrix, we have $n={n},$ since this is the number of components in each of the vectors of the null space. \n\nAlso, since \n\n$$\n'+r'\text{Null}(A)=\{'+expanded+r'\,|\,\,'+variables+r'\in R\}'+'\n$$\n\n'+f'we conclude that $\\text{{nullity}}(A)={k}.$\n\nTherefore,\n\n$$\n'+r'\begin{aligned}\text{rank}(A)+\text{nullity}(A) & =n \\ \text{rank}(A)+'+f'{k} & ={n}'+r' \\ \text{rank}(A) & ='+f'{n}-{k}'+r' \\  & ='+f'{answer}.'+r'\end{aligned}'+'\n$$'
    return normalize_prose(problem),normalize_prose(solution),answer

@checked_math_content
def generate(level,seed=0,template=None,parameters=None,profile=None,field_type=None,bank_anchor=None,bank_scale=None):
    if level not in SUPPORTED_LEVELS:raise ValueError('unsupported difficulty; hard has no validated source workload')
    if field_type not in (None,'radio',':answer-field.type/radio'):raise ValueError('radio required')
    r=random.Random(seed)
    if template in SOURCES:
        source=template
        if SOURCES[source][':question/difficulty'][':db/ident'].split('/')[-1]!=level:raise ValueError('source/level mismatch')
        template='column-basis' if level=='easy' else 'null-space-display' if source in ('q-35434','q-79350') else 'null-space-inline'
        profile=profile or SOURCE_PROFILE[source]
    else:source=None
    template=template or ('column-basis' if level=='easy' else r.choice(['null-space-inline','null-space-display']))
    if template not in (['column-basis'] if level=='easy' else ['null-space-inline','null-space-display']):raise ValueError('template/level mismatch')
    profile=profile or r.choice(PROFILES[level])
    if profile not in PROFILES[level]:raise ValueError('profile/level mismatch')
    if source and parameters is None:parameters=ORIGINAL[source]
    if parameters is None:
        p,anchor,scale,values=sample(level,r,profile)
        if bank_anchor is not None or bank_scale is not None:raise ValueError('bank translation requires explicit parameters')
    else:
        p=json.loads(json.dumps(parameters));anchor=None;scale=None
        if not valid(level,p,profile):raise ValueError('parameter/profile constraint')
        if source and p==ORIGINAL[source] and profile==SOURCE_PROFILE[source]:
            values=[int(a[':answer/value']) for a in SOURCES[source][':question/answer-fields'][0][':answer-field/choices']]
        elif level=='moderate':
            values=list(range(5)) if profile=='zero-through4' else list(range(1,6))
        else:
            candidates=bank_candidates(p,profile,p['n']-p['k'])
            if bank_anchor is not None:candidates=[c for c in candidates if c[0]==bank_anchor]
            if bank_scale is not None:candidates=[c for c in candidates if c[1]==bank_scale]
            if not candidates:raise ValueError('no compatible bank translation')
            anchor,scale,values,_=r.choice(candidates)
    if not valid(level,p,profile):raise ValueError('parameter/profile constraint')
    problem,solution,answer=render(level,p,template)
    values=sorted(values);content={'level':level,'problem':problem,'solution':solution,'values':values,'correct':answer}
    uid=ident(digest(content));fid=ident(uid+'/selection')
    choices=[{':answer/id':ident(fid+'/'+str(x)),':answer/type':':answer.type/math',':answer/value':normalize_tex(str(x))} for x in values]
    correct=next(a[':answer/id'] for a in choices if int(a[':answer/value'])==answer)
    q={':question/id':uid,':question/difficulty':':question.difficulty/'+level,':question/problem':problem,':question/worked-solution':solution,':question/answer-fields':[{':answer-field/id':fid,':answer-field/key':'selection',':answer-field/type':':answer-field.type/radio',':answer-field/choices':choices,':answer-field/correct':[':answer/id',correct]}]}
    task=['easy',p['n'],p['k']] if level=='easy' else ['moderate',[[str(x) for x in row] for row in sp.Matrix(p['matrix']).T.rref()[0].tolist()]]
    return {'knowledge_point':{'db_id':KP_ID,'id':str(NAMESPACE),'title':KP[':knowledge-point/title']},'question':q,'generation':{'version':VERSION,'seed':seed,'template':template,'profile':profile,'parameters':p,'bank_anchor':anchor,'bank_scale':scale,'source_replay':source,'bank_recipe':'exact source bank' if source and p==ORIGINAL[source] and profile==SOURCE_PROFILE[source] else 'translated source shape; qualifying value independently assigned' if level=='easy' else 'observed consecutive bank','correct_value':str(answer),'mathematical_fingerprint':digest(task),'content_fingerprint':digest(content),'source_question_ids':[s for s in SOURCES if SOURCE_PROFILE[s]==profile], 'source_basis':SNAPSHOT['basis'],'source_lineage':SNAPSHOT['lineage'],'dependencies':{'python':sys.version.split()[0],'sympy':sp.__version__},'plots':'none','domain':'real vector spaces; full column rank parameter coefficient matrix'}}

def generate_easy(seed=0,**kw):return generate('easy',seed,**kw)
def generate_moderate(seed=0,**kw):return generate('moderate',seed,**kw)
def markdown(rec):return rec['question'][':question/problem']+'\n\n'+rec['question'][':question/worked-solution']
def main():
    parser=argparse.ArgumentParser();parser.add_argument('--difficulty',choices=['easy','moderate','all'],default='all');parser.add_argument('--seed',type=int,default=0);parser.add_argument('--count',type=int,default=1);parser.add_argument('--format',choices=['json','markdown'],default='json');parser.add_argument('--template');parser.add_argument('--profile');a=parser.parse_args()
    records=[generate(l,a.seed+i,template=a.template,profile=a.profile) for l in (SUPPORTED_LEVELS if a.difficulty=='all' else [a.difficulty]) for i in range(a.count)]
    print(json.dumps(records,indent=2) if a.format=='json' else '\n\n---\n\n'.join(map(markdown,records)))
if __name__=='__main__':main()

# Instructional account and repair design

The learner applies rank(A)+nullity(A)=n, where n is the number of columns. Canonical example 10cc01a6-af19-5340-9743-ade4d5e252dc identifies rank from three column-basis vectors, then subtracts 3 from 5. Tutorial 0728c510-110b-5bde-93ea-9050a87a6ecc states the same theorem and identifies n as the number of vector components for a described null space. Prerequisites concern bases of column and null spaces; row reduction is not added to these questions.

Easy stages: inspect m by n, count the k listed column-basis vectors, infer rank=k, calculate n-k, select the integer. Moderate stages: count n components, expand the homogeneous vector in its two or three real parameters, identify the number of independent coefficient vectors, calculate rank=n-k, select the integer. Both retain one five-choice radio field and a concrete worked solution stating the theorem, identifying dimensions, substituting and subtracting. Full column rank is required so parameter counting is justified. No diagrams occur in the assessed source; prerequisite images describe other exercises and are not output assets.

Observed easy cases use m=3..6, n=5..10, k=2..5 (seven questions). Observed moderate cases use n=4 or 5, k=2 or 3, indices [1,2], [2,3], or [1,2,3] (eight questions). In particular 5e7c8be1-d271-506d-bfc9-fbf1881a88d8, 7663d433-7983-5195-82f9-f8b3b6b0d6aa and 1b45e803-c138-5bcf-9207-424394814f56 require five components. The older bundled basis-2516 snapshot contained only eleven cases; it is retained as historical evidence, but the supplied basis-5443 source with fifteen cases governs this repair. No mathematical source errors were found. Set delimiter sizing and algebraic term ordering may be normalized without changing values or solution stages.

Answer-bearing assignments are the integer n-k and the numeric option that represents it. Easy n and k vary; m is contextual and may vary independently when feasible. Moderate n, k, coefficient supports and coefficients vary; relabeling independent parameters is irrelevant to rank. The requested invariant stays nullity for column-basis prompts and rank for null-space prompts because reversing supplied/requested roles changes the exercise. Positive k and n-k retain the source nontrivial spaces. Moderate n stays in {4,5} and k in {2,3}, preserving the demonstrated expansion workload. Dependent parameters are excluded because deciding dependence would add a new learner task. Coefficients remain integers -3..3, the established conservative extension. Easy limits m=2..7,n=4..12 retain short basis lists and one subtraction; feasible k is 1..min(m,n-1). Hard has no source workload and is unsupported; easy and moderate are supported.

The former answer-relative offsets forced a fixed numeric answer position. In normal generation the easy bank is now a translated observed *shape*, independent of a designated correct position: consecutive offsets [0,1,2,3,4], gapped offsets [0,2,3,4,5], or dimension-bank offsets [0,1,2,3,5] at scale 1 or 2 (scale 2 reproduces the observed [0,2,4,6,10]). The primitive integer scale retains this bank shape when the feasible nullity interval is too short to contain two even-spaced candidates. These are explicitly authored extensions of complete observed banks, not inferred learner mistakes. Choose m,n and a bank shape/translation with at least two feasible nullities, then assign the qualifying value among those candidates and derive k=n-value. Thus the same complete bank and same matrix dimensions can require different choices as the basis cardinality changes. No new feedback or error interpretations are invented. For explicit parameters choose a compatible translation with the same two-answer support; all mathematical parameter instances remain representable. Source-ID replay uses the exact original complete bank. It does not define a separate learner-visible layout and every source bank shape is also exercised in normal sampling with varying correct positions.

Moderate retains the two observed complete banks 0..4 and 1..5. Both contain all supported ranks 1,2,3 and neither fixes the answer. Sample n and k before coefficients; both two-parameter index sets are eligible at both component counts. Fixed five-option count preserves the source response contract. Sorted numeric choices preserve the existing UI contract; numeric order must not identify correctness. Choosing a basis count or counting independent coefficient vectors is the intended reasoning, not a shortcut.

Coverage obligations: replay all fifteen complete banks and the canonical example; test all observed bank shapes and both moderate layouts, component counts and parameter counts/index sets. Hold easy m,n and bank fixed while changing k; hold k and bank fixed while changing n; change m alone and retain the response. Add a moderate zero component to change n and the rank, add an independent parameter to change k and rank, and change an irrelevant coefficient while preserving dimension. Independently parse rendered prompts and worked solutions, check every native radio selection, probe bank gaps, numeric rank, endpoints and layout before/after shared delivery filtering, and audit the regenerated five-record batch at its retained seeds. Selection uses difficulty and fresh-question identity, not the answer; actual learner history remains unavailable and is stated as a limit.
